SINA_SMART["hemato1-platelets"] = {"lecture":"hemato1-platelets","title":"Thrombocytopenia and thrombocytosis","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"hemato1-platelets:e0","text":"Thrombocytopenia < 150,000/µL; often asymptomatic > 50,000.","topic":"Thrombocytopenia: definition and signs","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-platelets:e1","text":"< 20,000 spontaneous mucosal bleeding; < 10,000 life-threatening.","topic":"Thrombocytopenia: definition and signs","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-platelets:e2","text":"Mucocutaneous bleeding = platelet disorder; joints/deep = factor deficiency.","topic":"Thrombocytopenia: definition and signs","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-platelets:e3","text":"Mechanisms: ↓ production, ↑ destruction (ITP, drugs, DIC), sequestration.","topic":"Mechanisms and evaluation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-platelets:e4","text":"Always exclude EDTA pseudo-thrombocytopenia (smear, citrate tube).","topic":"Mechanisms and evaluation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-platelets:e5","text":"Isolated → ITP; pancytopenia → marrow failure, leukaemia, B12/folate.","topic":"Mechanisms and evaluation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-platelets:e6","text":"Treat the cause; prednisone first-line for ITP.","topic":"Management of thrombocytopenia","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-platelets:e7","text":"Transfuse: < 10k prophylaxis, < 20k with risk, < 50k minor procedure, < 75k surgery, < 100k neuro/eye.","topic":"Management of thrombocytopenia","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-platelets:e8","text":"Thrombocytosis > 400,000: reactive > 80% (infection, iron deficiency, splenectomy) vs clonal < 20%.","topic":"Thrombocytosis","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-platelets:e9","text":"Clonal: thrombosis, paradoxical bleeding; aspirin ± cytoreduction.","topic":"Thrombocytosis","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"422dus":"a","135117v":"a","1d22zmf":"a","1bqg26f":"a","18bgxh2":"a","iqx526":"a","1hwvetv":"a","o21i6n":"a","a9noev":"a","19uhewk":"a","79213s":"a","roli9v":"a","19b1rph":"a","dxwpky":"a","bddpz0":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"hemato1-platelets:e0":{"s":0,"u":["Thrombocytopenia < 150,000/µL; often asymptomatic > 50,000.","Thrombocytopenia : platelets &lt; 150,000/µL , one of the most common haematological abnormalities, often asymptomatic above 50,000 and sometimes the first sign of infection, drug toxicity, autoimmunity or marrow disease.","Bleeding thresholds: &gt; 50,000 usually no spontaneous bleeding (minor procedures safe); 20,000-50,000 bleeding with trauma or procedures; &lt; 20,000 spontaneous mucosal bleeding; &lt; 10,000 life-threatening bleeding (GI, intracranial); platelet function and coagulation also matter."],"dp":[]},"hemato1-platelets:e1":{"s":0,"u":["< 20,000 spontaneous mucosal bleeding; < 10,000 life-threatening.","Bleeding thresholds: &gt; 50,000 usually no spontaneous bleeding (minor procedures safe); 20,000-50,000 bleeding with trauma or procedures; &lt; 20,000 spontaneous mucosal bleeding; &lt; 10,000 life-threatening bleeding (GI, intracranial); platelet function and coagulation also matter.","Thrombocytopenia : platelets &lt; 150,000/µL , one of the most common haematological abnormalities, often asymptomatic above 50,000 and sometimes the first sign of infection, drug toxicity, autoimmunity or marrow disease."],"dp":[]},"hemato1-platelets:e2":{"s":0,"u":["Mucocutaneous bleeding = platelet disorder; joints/deep = factor deficiency.","Joint and deep tissue bleeding suggests a coagulation factor deficiency instead."],"dp":[]},"hemato1-platelets:e3":{"s":1,"u":["Mechanisms: ↓ production, ↑ destruction (ITP, drugs, DIC), sequestration.","Three mechanisms, possibly combined: decreased production (aplastic anaemia, myelodysplasia, chemotherapy, alcohol, some antibiotics, HIV, EBV, B12 or folate deficiency), increased destruction (immune: immune thrombocytopenia (ITP) ; drugs: quinine, heparin, antibiotics; non-immune: sepsis, DIC , where widespread clotting consumes platelets and factors, causing thrombosis and bleeding together) and sequestration (hypersplenism)."],"dp":[{"h":"Why platelet transfusion can fail in ITP","t":"In immune thrombocytopenia, antibodies coat platelets and macrophages in the spleen destroy them within hours. Transfused platelets carry the same targets and are destroyed just as fast, so the count barely rises. Treatment therefore aims at the immune attack (corticosteroids first), keeping transfusions for life-threatening bleeding. Source: the lecture's management slides."}]},"hemato1-platelets:e4":{"s":1,"u":["Always exclude EDTA pseudo-thrombocytopenia (smear, citrate tube).","Rule out pseudo-thrombocytopenia first : EDTA can make platelets clump, falsely lowering the count; the smear shows clumps and a citrate-tube recount is normal."],"dp":[]},"hemato1-platelets:e5":{"s":1,"u":["Isolated → ITP; pancytopenia → marrow failure, leukaemia, B12/folate.","Patterns: isolated thrombocytopenia → ITP or inherited disorder; pancytopenia → marrow failure, leukaemia, severe infection, B12/folate deficiency; with neutrophilia → infection; with lymphocytosis → viral infection or lymphoid malignancy.","Further tests as guided: cultures, HIV and viral serology, B12/folate, anti-platelet antibodies, ANA, liver tests; marrow if unclear."],"dp":[]},"hemato1-platelets:e6":{"s":2,"u":["Treat the cause; prednisone first-line for ITP.","Treat the cause : antibiotics or antivirals, stop the offending drug, corticosteroids (prednisone) first-line for ITP , B12 or folate replacement; monitor counts."],"dp":[]},"hemato1-platelets:e7":{"s":2,"u":["Transfuse: < 10k prophylaxis, < 20k with risk, < 50k minor procedure, < 75k surgery, < 100k neuro/eye.","Thresholds: &lt; 10,000 prophylaxis in stable patients; &lt; 20,000 with bleeding, fever, infection or coagulopathy; &lt; 50,000 before minor procedures or with active bleeding; &lt; 75,000 before general surgery; &lt; 100,000 before neurosurgery or eye surgery."],"dp":[]},"hemato1-platelets:e8":{"s":3,"u":["Thrombocytosis > 400,000: reactive > 80% (infection, iron deficiency, splenectomy) vs clonal < 20%.","Reactive (&gt; 80%) , temporary and benign: infection or inflammation, iron deficiency , surgery, trauma, splenectomy , haemolysis, bleeding.","Platelets &gt; 400,000/µL , usually found incidentally."],"dp":[]},"hemato1-platelets:e9":{"s":3,"u":["Clonal: thrombosis, paradoxical bleeding; aspirin ± cytoreduction.","Complications (mainly clonal): thrombosis (stroke, TIA, MI, DVT; microvascular headache, visual changes, tingling) and paradoxical bleeding at extreme counts.","Management: reactive → treat the cause, no antiplatelet therapy even if very high; clonal → low-dose aspirin and cytoreduction in high-risk patients."],"dp":[]}},"meta":{"422dus":{"a":"recall","vg":"hemato1-platelets:e0/recall/1"},"135117v":{"a":"recall","vg":"hemato1-platelets:e1/recall/1"},"1d22zmf":{"a":"recall","vg":"hemato1-platelets:e2/recall/1"},"1bqg26f":{"a":"relationship","vg":"hemato1-platelets:e3/relationship/1"},"18bgxh2":{"a":"recall","vg":"hemato1-platelets:e3/recall/1"},"iqx526":{"a":"recall","vg":"hemato1-platelets:e9/recall/1"},"1hwvetv":{"a":"recall","vg":"hemato1-platelets:e4/recall/1"},"o21i6n":{"a":"recall","vg":"hemato1-platelets:e5/recall/1"},"a9noev":{"a":"recall","vg":"hemato1-platelets:e4/recall/2"},"19uhewk":{"a":"recall","vg":"hemato1-platelets:e6/recall/1"},"79213s":{"a":"recall","vg":"hemato1-platelets:e7/recall/1"},"roli9v":{"a":"application","vg":"hemato1-platelets:e7/application/1"},"19b1rph":{"a":"recall","vg":"hemato1-platelets:e8/recall/1"},"dxwpky":{"a":"recall","vg":"hemato1-platelets:e8/recall/2"},"bddpz0":{"a":"recall","vg":"hemato1-platelets:e8/recall/3"}},"explRev":"1d040dba1fcb"};
